class Solution {
public:
    int findDerangement(int n) {
        const long long MOD = 1000000007LL;
        if (n == 0) {
            return 1;
        }
        long long before = 1, previous = 0;
        for (int i = 2; i <= n; ++i) {
            long long current = (i - 1LL) * (previous + before) % MOD;
            before = previous;
            previous = current;
        }
        return static_cast<int>(previous);
    }
};
